import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Realtime In-App Notification Center (PostgreSQL LISTEN/NOTIFY + WebSocket/SSE)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/02-agency-studio-plans/realtime-notification-center/spec.md","filePath":"feature/modules/02-agency-studio-plans/realtime-notification-center/spec.md"}'),n={name:"feature/modules/02-agency-studio-plans/realtime-notification-center/spec.md"};function r(s,e,c,d,l,f){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="realtime-in-app-notification-center-postgresql-listen-notify-websocket-sse" tabindex="-1">Realtime In-App Notification Center (PostgreSQL LISTEN/NOTIFY + WebSocket/SSE) <a class="header-anchor" href="#realtime-in-app-notification-center-postgresql-listen-notify-websocket-sse" aria-label="Permalink to &quot;Realtime In-App Notification Center (PostgreSQL LISTEN/NOTIFY + WebSocket/SSE)&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>realtime-notification-center</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>02-agency-studio-plans</code> — Agency, Personal Studio, Dashboards &amp; Realtime Notifications</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>realtime-notifications</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/09-admin-functions/3-10-1-push-notification/spec.html">FR 3.10.1 — Push Notification</a> · <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver low-latency, persistent in-app notifications (<code>user_notifications</code>) across Web and Mobile for Task assignments, 3-tier approval transitions, <code>@mention</code> comments/chat, Content Request submissions, Social Post publish completions/failures, and Admin system broadcasts, powered by PostgreSQL <code>LISTEN/NOTIFY</code> (<code>2026-11-21-user-notification-realtime.sql</code>) and WebSocket/STOMP push.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, or <code>Admin</code>, I want an instant unread badge and notification inbox that updates in real time without polling storms and deep-links me directly to the target Task, Campaign, Chat thread, or Post.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Durable Persistence + <code>pg_notify</code> Trigger (<code>2026-11-21-user-notification-realtime.sql</code>):</strong> Every domain event inserts a row into <code>user_notifications</code> (<code>recipient_user_id</code>, <code>type</code>, <code>title</code>, <code>body</code>, <code>action_url</code>, <code>metadata</code> JSONB, <code>read_at</code>) and fires PostgreSQL <code>NOTIFY user_notifications_channel</code> after transaction commit.</li><li><strong>Realtime Fan-Out &amp; Reconnect Catch-Up:</strong> Dedicated listener connection in <code>brandhub-business-service</code> pushes new notifications over authenticated STOMP/WebSocket user queues (<code>/user/queue/notifications</code>); on reconnect or tab focus, <code>GET /api/v1/notifications/me</code> reconciles any missed items.</li><li><strong>Read / Read-All State &amp; Deep-Link Validation:</strong> <code>POST /api/v1/notifications/me/{id}/read</code> and <code>POST /api/v1/notifications/me/read-all</code> update <code>read_at</code> idempotently; <code>notificationLink.ts</code> validates deep-link routes and switches active Workspace/Agency safely before navigating.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>notifications.{title,markAllRead,empty,types.*,timeAgo}</code> in <code>src/i18n/locales/{vi,en}/notifications.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> Header Notification Bell popover + Notification Inbox drawer (<code>brandhub-web</code>)</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/notifications/NotificationsScreen.tsx</code>, <code>NotificationPreferencesScreen.tsx</code>, <code>src/services/notificationService.ts</code>, <code>src/utils/notificationLink.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/notifications/me?page={1}&amp;size={20}&amp;unreadOnly={bool}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client, Admin</code>)</td><td style="text-align:left;"><code>UserNotificationController</code> -&gt; paginated inbox + unread count</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/notifications/me/{id}/read</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client, Admin</code>)</td><td style="text-align:left;"><code>UserNotificationController</code> -&gt; marks single notification read (<code>recipient_user_id</code> checked)</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/notifications/me/read-all</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client, Admin</code>)</td><td style="text-align:left;"><code>UserNotificationController</code> -&gt; marks all unread notifications read for caller</td></tr><tr><td style="text-align:left;"><code>WS /ws -&gt; /user/queue/notifications</code></td><td style="text-align:left;">Authenticated STOMP JWT</td><td style="text-align:left;"><code>WebSocketConfig</code> + <code>PgNotificationListener</code> -&gt; pushes live <code>UserNotificationResponse</code></td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Revoked Workspace rostership Before Click:</strong> Clicking an older notification for a Workspace the user was removed from displays a safe localized access notice instead of crashing.</li><li><strong>PostgreSQL Listener Connection Drop:</strong> Automatic exponential-backoff reconnect re-issues <code>LISTEN</code> without impacting primary HikariCP transactional pool.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/09-admin-functions/3-10-1-push-notification/spec.html">FR 3.10.1 — Push Notification</a> · <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA 03 Agency &amp; Workspace</a> · <a href="./../../../../ba/09-admin-functions.html">BA 09 Admin Functions</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
